#!/usr/bin/env python3
"""
Share card v2: the site's current hero art, and the title now ends at "Tests".

What changed from v1:
  1. the card now uses the new vector sperm set that is live on the homepage
     (components/hero-line-stage.tsx: the egg plus all fourteen swimmers),
     rendered at full strength in deep green and masked off the copy column,
     instead of the older flat fertility-hero-ovary-sperm.png
  2. the title no longer says "For Women": "At-Home Fertility & Hormone Tests | FertiTerra"

Safe to re-run. Backs up app/layout.tsx to .bak-before-share-card-v2.
"""
import base64
import re
from pathlib import Path

OG_PNG = base64.b64decode("")

TITLE = "At-Home Fertility & Hormone Tests | FertiTerra"
DESC = (
    "Get clinical-grade fertility and hormone insights, specialist access, "
    "and a personalised care plan. Your reproductive health journey, fully supported."
)

OPENGRAPH = """openGraph: {
    title: "%s",
    description:
      "%s",
    url: "https://fertiterratechnologies.com",
    siteName: "FertiTerra",
    images: [
      {
        url: "/images/og-fertiterra.png",
        width: 1200,
        height: 630,
        alt: "FertiTerra at-home fertility and hormone tests",
      },
    ],
    locale: "en_US",
    type: "website",
  },""" % (TITLE, DESC)

TWITTER = """twitter: {
    card: "summary_large_image",
    title: "%s",
    description:
      "%s",
    images: ["/images/og-fertiterra.png"],
  },""" % (TITLE, DESC)


def replace_object(src, key, new_block):
    start = src.find(key + ": {")
    if start == -1:
        return src, False
    i = src.index("{", start)
    depth = 0
    for j in range(i, len(src)):
        if src[j] == "{":
            depth += 1
        elif src[j] == "}":
            depth -= 1
            if depth == 0:
                end = j + 1
                if end < len(src) and src[end] == ",":
                    end += 1
                rest = src[end:]
                if not rest.startswith("\n"):
                    rest = "\n" + rest
                return src[:start] + new_block + rest, True
    return src, False


def main():
    if not Path("app").is_dir() or not Path("package.json").is_file():
        print("Run this from the Fertiterra folder.")
        return

    layout = Path("app/layout.tsx")
    if not layout.is_file():
        print("app/layout.tsx not found.")
        return

    img = Path("public/images/og-fertiterra.png")
    img.parent.mkdir(parents=True, exist_ok=True)
    img.write_bytes(OG_PNG)
    print("wrote public/images/og-fertiterra.png (1200x630, %d KB)" % (len(OG_PNG) // 1024))

    before = layout.read_text(encoding="utf-8")
    src, ok_og = replace_object(before, "openGraph", OPENGRAPH)
    src, ok_tw = replace_object(src, "twitter", TWITTER)

    if not (ok_og and ok_tw):
        print("metadata: could not find the openGraph/twitter block, layout.tsx untouched")
        print("  openGraph found:", ok_og, " twitter found:", ok_tw)
        return

    src = re.sub(r'title: "[^"]*",', 'title: "%s",' % TITLE, src, count=1)
    src = re.sub(r'description:\s*\n?\s*"[^"]*",', 'description:\n    "%s",' % DESC, src, count=1)

    if src != before:
        layout.with_suffix(".tsx.bak-before-share-card-v2").write_text(before, encoding="utf-8")
        layout.write_text(src, encoding="utf-8")
        print("metadata: title is now \"%s\"" % TITLE)
        print("  backup: app/layout.tsx.bak-before-share-card-v2")
    else:
        print("metadata: already up to date")

    print("")
    print("Restart the dev server: Ctrl+C, then  rm -rf .next && pnpm dev")
    print("Then push, and press Scrape Again at https://developers.facebook.com/tools/debug/")


if __name__ == "__main__":
    main()
